-- ══════════════════════════════════════════════════════════════════
-- v27 — AI Learning Paths / Roadmaps (ai_paths)
-- Run in: Supabase Dashboard → SQL Editor
-- HYBRID type (same approach as v25 ai_courses / v26 ai_projects):
--   • Real columns for every flat/primitive field
--   • JSONB for the one genuinely-nested array-of-object field:
--     nodes (RoadmapNode[]: id/titleAr/titleEn/descriptionAr/descriptionEn/
--            duration/skills/status/courseId)
-- ══════════════════════════════════════════════════════════════════

-- 1. Table
CREATE TABLE IF NOT EXISTS ai_paths (
  id                  TEXT        PRIMARY KEY,                 -- = existing slug (e.g. 'beginner-ai') — keeps links intact
  portal_id           TEXT        NOT NULL DEFAULT 'ai-academy',
  content_type        TEXT        NOT NULL DEFAULT 'path',
  status              TEXT        NOT NULL DEFAULT 'published'
                                  CHECK (status IN ('published','draft','archived')),
  featured            BOOLEAN     NOT NULL DEFAULT false,
  sort_order          INT         NOT NULL DEFAULT 0,
  title_ar            TEXT        NOT NULL DEFAULT '',
  title_en            TEXT        NOT NULL DEFAULT '',
  description_ar      TEXT        NOT NULL DEFAULT '',
  description_en      TEXT        NOT NULL DEFAULT '',
  level               TEXT        NOT NULL DEFAULT 'beginner'
                                  CHECK (level IN ('beginner','intermediate','advanced')),
  total_weeks         INT         NOT NULL DEFAULT 0,
  outcome             TEXT        NOT NULL DEFAULT '',
  outcome_ar          TEXT        NOT NULL DEFAULT '',
  icon                TEXT        NOT NULL DEFAULT '🚀',
  color               TEXT        NOT NULL DEFAULT 'blue',
  nodes               JSONB       NOT NULL DEFAULT '[]'::jsonb,  -- RoadmapNode[]
  created_by          UUID        REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  archived_at         TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_ai_paths_status ON ai_paths (status);
CREATE INDEX IF NOT EXISTS idx_ai_paths_level  ON ai_paths (level);

-- 2. Auto-update updated_at
CREATE OR REPLACE FUNCTION update_ai_paths_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;

DROP TRIGGER IF EXISTS trg_ai_paths_updated_at ON ai_paths;
CREATE TRIGGER trg_ai_paths_updated_at
  BEFORE UPDATE ON ai_paths
  FOR EACH ROW EXECUTE FUNCTION update_ai_paths_updated_at();

-- 3. RLS
ALTER TABLE ai_paths ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "public_read_published_ai_paths" ON ai_paths;
CREATE POLICY "public_read_published_ai_paths"
  ON ai_paths FOR SELECT
  USING (status = 'published');

DROP POLICY IF EXISTS "admin_manage_ai_paths" ON ai_paths;
CREATE POLICY "admin_manage_ai_paths"
  ON ai_paths FOR ALL
  USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'))
  WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));

-- Service role (API routes using createAdminClient) bypasses RLS — application
-- code verifies admin role before writes, matching the existing tables' convention.

